    let mut md_out: Option<PathBuf> = None;
    let mut quality_md: Option<PathBuf> = None;
    let mut quality_json: Option<PathBuf> = None;

    let mut index = 0;
    while index < args.len() {
        let arg = args[index].as_str();
        let next = |index: &mut usize| -> String {
            *index += 1;
            args.get(*index).cloned().unwrap_or_default()
        };
        match arg {
            "micro" | "e2e" | "all" | "quality" | "sweep" => mode = arg.to_string(),
            "--sizes" => sizes = next(&mut index),
            "--samples" => samples = next(&mut index).parse().unwrap_or(samples),
            "--kd" => kd = next(&mut index),
            "--no-idle" => no_idle = true,
            "--json" => json_out = Some(PathBuf::from(next(&mut index))),
            "--out" => md_out = Some(PathBuf::from(next(&mut index))),
            "--quality-out" => quality_md = Some(PathBuf::from(next(&mut index))),
            "--quality-json" => quality_json = Some(PathBuf::from(next(&mut index))),
            "--quick" => {
                sizes = "200".to_string();
                samples = 5;
            }
            "--help" | "-h" => {
                println!(
                    "uso: knudge-bench [micro|e2e|quality|sweep|all] [--sizes 200,1000] [--samples 8] [--kd PATH] [--json out.json] [--out report.md] [--quality-out bench/qualidade.md] [--quality-json bench/qualidade.json] [--quick]"
                );
                return;
            }
            other => {
                eprintln!("argumento desconhecido: {other}");
                std::process::exit(2);
            }
        }
        index += 1;
    }

    let sizes: Vec<usize> = sizes
        .split(',')
        .filter_map(|part| part.trim().parse().ok())
        .collect();
    let sizes = if sizes.is_empty() {
        vec![200, 1000]
    } else {
        sizes
    };

    let mut harness = Harness::new();
    if mode == "micro" || mode == "all" {
        eprintln!("== micromb (sizes={sizes:?}) ==");
        micro::run(&mut harness, &sizes);
    }
    if mode == "e2e" || mode == "all" {
        let kd = PathBuf::from(&kd);
        let absolute = if kd.is_absolute() {
            kd
        } else {
            std::env::current_dir().unwrap_or_default().join(kd)
        };
        eprintln!(
            "== ponta-a-ponta (kd={}, sizes={sizes:?}) ==",
