        eprintln!("== qualidade de retrieval ==");
        let md = quality_md.unwrap_or_else(|| PathBuf::from("bench/qualidade.md"));
        let json = quality_json.unwrap_or_else(|| PathBuf::from("bench/qualidade.json"));
