import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";
import {
  formatKdAi,
  kdAiHelp,
  parseKdAiCommand,
  runKdAi,
  type KdAiResult,
} from "./kd-ai.ts";
import {
  rememberSessionRun,
  type SessionRun,
  type SessionTool,
} from "./memory-store.ts";

/**
 * omp ⇄ knudge `kd ai`.
 *
 * Registration is not a model choice: every completed run is projected into the agent-owned
 * JSONL store from omp lifecycle events, then flushed before the stop hook settles. The model
 * only gets `knudge_ai` (optional query) and `/kd-ai` (optional user query).
 *
 * The knudge side stays read-only. Notes carry `provenance.activity=derive`; the run projection
 * is written to both `memory` and `session-log` so either `kd ai` area can answer.
 */
export default function knudgeAi(pi: ExtensionAPI) {
  const z = pi.zod;
  const pendingBySession = new Map<string, unknown[]>();

  pi.registerTool({
    name: "knudge_ai",
    label: "Knudge AI Memory",
    description:
      "Consulta read-only a memória de agente indexada pelo knudge (`kd ai`). " +
      "Use `memory` para `.agents/memory/notes.jsonl` e `session-log` para a projeção do log " +
      "de sessão. Com `query`, faz recall por significado; sem `query`, lista a fonte.",
    parameters: z.object({
      area: z
        .enum(["memory", "session-log"])
        .optional()
        .describe("Fonte consultada; default memory"),
      query: z
        .string()
        .optional()
        .describe("Consulta textual; omitida, lista a fonte (id|tipo|statement)"),
      limit: z
        .number()
        .int()
        .positive()
        .optional()
        .describe("Máximo de hits no recall"),
      source: z
        .string()
        .optional()
        .describe("Fonte JSONL explícita, relativa ao cwd ou absoluta"),
    }),
    approval: "read",
    loadMode: "essential",
    async execute(_toolCallId, params, signal, _onUpdate, ctx) {
      const result = await runKdAi(
        {
          area: params.area,
          query: params.query,
          limit: params.limit,
          source: params.source,
        },
        { cwd: ctx.cwd, signal },
      );
      const text = formatKdAi(result);
      return {
        content: [{ type: "text", text }],
        details: toolDetails(result),
        isError: !result.ok,
      };
    },
  });

  pi.registerCommand("kd-ai", {
    description: "Consultar a memória de agente do knudge (`kd ai`, read-only)",
    getArgumentCompletions: (prefix: string) =>
      [
        { value: "memory", label: "memory", description: "memória do agente" },
        { value: "session-log", label: "session-log", description: "projeção do log de sessão" },
        { value: "--source ", label: "--source", description: "fonte JSONL explícita" },
        { value: "--limit ", label: "--limit", description: "máximo de hits" },
      ].filter((item) => item.value.startsWith(prefix)),
    handler: async (args, ctx) => {
      const parsed = parseKdAiCommand(args);
      if (parsed.help) {
        pi.sendMessage(
          {
            customType: "knudge-ai",
            content: kdAiHelp(),
            display: true,
            attribution: "agent",
          },
          { triggerTurn: false },
        );
        return;
      }
      if (parsed.error) {
        if (ctx.hasUI) ctx.ui.notify(parsed.error, "warning");
        return;
      }

      const result = await runKdAi(parsed.request, { cwd: ctx.cwd });
      pi.sendMessage(
        {
          customType: "knudge-ai",
          content: formatKdAi(result),
          display: true,
          attribution: "agent",
        },
        { triggerTurn: false },
      );

      if (ctx.hasUI) {
        const summary = result.ok
          ? `kd ai ${result.area}: ${result.mode === "list" ? `${result.notes.length} nota(s)` : `${result.hits.length} hit(s)`}`
          : `kd ai falhou: ${result.code}`;
        ctx.ui.notify(summary, result.ok ? "info" : "error");
      }
    },
  });

  // Every finalized message is buffered; the stop hook flushes one deterministic run note.
  pi.on("message_end", (event, ctx) => {
    const key = sessionKey(ctx);
    const messages = pendingBySession.get(key) ?? [];
    messages.push(event.message);
    pendingBySession.set(key, messages);
  });

  pi.on("session_start", (_event, ctx) => {
    pendingBySession.delete(sessionKey(ctx));
  });

  const flush = async (ctx: SessionContext) => {
    const key = sessionKey(ctx);
    const messages = pendingBySession.get(key) ?? [];
    pendingBySession.delete(key);
    const run = extractRun(messages);
    if (!run) return;

    const result = await rememberSessionRun(run, { cwd: ctx.cwd });
    if (!result.ok) {
      pi.logger.error(
        `knudge-ai: registo automático falhou [${result.code}]: ${result.message}`,
      );
    } else if (result.warnings.length > 0) {
      pi.logger.warn(`knudge-ai: ${result.warnings.join("; ")}`);
    }
  };

  pi.on("session_stop", async (_event, ctx) => {
    await flush(ctx);
  });

  // Subagent sessions never fire session_stop; agent_end is the terminal fallback. `flush`
  // splices the buffer, so the main session's stop-then-agent_end order writes exactly once.
  pi.on("agent_end", async (event, ctx) => {
    if (event?.isTerminal === false) return;
    await flush(ctx);
  });

  pi.on("session_shutdown", async (_event, ctx) => {
    await flush(ctx);
  });
}

interface SessionContext {
  cwd: string;
  sessionManager?: {
    getSessionId?: () => string | undefined;
  };
}

function sessionKey(ctx: SessionContext): string {
  return ctx.sessionManager?.getSessionId?.() ?? "default";
}

function toolDetails(result: KdAiResult) {
  if (!result.ok) {
    return {
      ok: false,
      code: result.code,
      message: result.message,
      area: result.area,
      source: result.source,
      query: result.query,
      warnings: result.warnings,
      exitCode: result.exitCode,
    };
  }
  return {
    ok: true,
    area: result.area,
