 * Project the messages since the last user prompt into one run.
 *
 * Only user/assistant text is kept; tool names are recorded as metadata. This is deterministic:
 * the same transcript always produces the same statement, body, and content-addressed id.
 */
function extractRun(messages: unknown[]): SessionRun | undefined {
  let lastUser = -1;
  for (let index = 0; index < messages.length; index++) {
    if (roleOf(messages[index]) === "user") lastUser = index;
  }
  const run = lastUser >= 0 ? messages.slice(lastUser) : messages;

  const userText = run
    .filter((message) => roleOf(message) === "user")
    .map(messageText)
    .filter(Boolean)
    .join("\n\n");
  const assistantText = run
    .filter((message) => roleOf(message) === "assistant")
    .map(messageText)
    .filter(Boolean)
    .join("\n\n");

  if (!userText && !assistantText) return undefined;
  return { userText, assistantText, tools: collectTools(run) };
}

