/**
 * Deterministic projection of one completed run into separate notes.
 *
 * `memory` gets durable outcomes (decision + verification). `session-log` gets the full trace
 * (tools, files, commands, decision, verification).
 */
export function deriveSessionNotes(run: SessionRun, cwd?: string): DerivedNote[] {
  const notes: DerivedNote[] = [];
  const add = (request: RememberRequest, memory: boolean) => {
    const built = buildAgentNote({ ...request, area: "memory", activity: "derive" });
    if (built.ok) notes.push({ note: built.note, line: built.line, memory });
  };

  const tools = run.tools ?? [];
  const toolNames = [...new Set(tools.map((tool) => tool.name).filter(Boolean))];
  for (const name of toolNames) {
    const calls = tools.filter((tool) => tool.name === name);
    const body = calls
      .map((tool) => toolSummary(tool))
      .join("\n");
    add(
      {
        statement: `omp usou ${name}`,
        body: truncateText(`## chamadas\n${body}`, BODY_MAX),
        type: "fact",
        tags: ["omp", "session", "tool"],
        classification: "observational",
      },
      false,
    );
  }

  const readPaths = new Set<string>();
  const writtenPaths = new Set<string>();
  for (const tool of tools) {
    if (tool.name === "read") {
      for (const path of toolPaths(tool)) {
        const anchor = toAnchor(path, cwd);
        if (!anchor || readPaths.has(anchor)) continue;
        readPaths.add(anchor);
        add(
          {
            statement: `omp leu ${anchor}`,
            body: `## leitura\n${anchor}\n\nferramenta: read`,
            type: "fact",
            anchors: [anchor],
            tags: ["omp", "session", "file-read"],
            classification: "observational",
          },
          false,
        );
      }
    }
    if (tool.name === "write" || tool.name === "edit" || tool.name === "ast_edit") {
      for (const path of toolPaths(tool)) {
        const anchor = toAnchor(path, cwd);
        if (!anchor || writtenPaths.has(anchor)) continue;
        writtenPaths.add(anchor);
        add(
          {
            statement: `omp ${tool.name === "write" ? "escreveu" : "alterou"} ${anchor}`,
            body: `## escrita\n${anchor}\n\nferramenta: ${tool.name}`,
            type: "fact",
            anchors: [anchor],
            tags: ["omp", "session", "file-write"],
            classification: "observational",
          },
          false,
        );
      }
    }
  }

  for (const tool of tools) {
    if (tool.name !== "bash") continue;
    const command = stringArg(tool.arguments, "command");
    if (!command) continue;
    add(
      {
        statement: truncateScalars(`comando: ${normalize(command)}`, STATEMENT_MAX),
        body: truncateText(
          [
            `## comando`,
            "```sh",
            command,
            "```",
            "",
            "## resultado",
            tool.output?.trim() || "(sem saída)",
          ].join("\n"),
          BODY_MAX,
        ),
        type: tool.isError ? "error" : "fact",
        tags: ["omp", "session", "command"],
        classification: "observational",
      },
      false,
    );
  }

  if (run.assistantText.trim()) {
    const decision = firstSentence(run.assistantText);
    if (decision && !isVerificationStatement(decision)) {
      const anchors = writtenPaths.size > 0 ? [...writtenPaths] : undefined;
      add(
        {
          statement: truncateScalars(decision, STATEMENT_MAX),
          body: truncateText(run.assistantText, BODY_MAX),
          type: "decision",
          anchors,
          tags: ["omp", "session", "decision"],
          classification: "tactical",
        },
        true,
      );
    }
  }

  for (const line of verificationLines(run.assistantText)) {
    add(
      {
        statement: truncateScalars(stripMarkdown(line), STATEMENT_MAX),
        body: `## verificação\n${line}`,
        type: "fact",
        tags: ["omp", "session", "verification"],
        classification: "observational",
      },
      true,
    );
  }

  const seen = new Set<string>();
  return notes.filter((entry) => {
    if (seen.has(entry.note.id)) return false;
    seen.add(entry.note.id);
    return true;
  });
}

/**
 * Write the run projection: every note to `session-log`, durable notes to `memory`.
 * Append-only; knudge dedups on read by `id` (last line wins).
 */
export async function rememberSessionRun(
  run: SessionRun,
  options: RememberOptions = {},
): Promise<RememberResult> {
  const notes = deriveSessionNotes(run, options.cwd);
  if (notes.length === 0) {
    return {
      ok: true,
      paths: [],
      warnings: [],
      notes: [],
      counts: { sessionLog: 0, memory: 0 },
    };
  }
  if (options.signal?.aborted) {
    return { ok: false, code: "aborted", message: "registo cancelado" };
  }

  const targets: Array<{ area: KdAiArea; notes: DerivedNote[] }> = [
    { area: "session-log", notes },
    { area: "memory", notes: notes.filter((entry) => entry.memory) },
  ];

  const paths: string[] = [];
  const warnings: string[] = [];
  const counts = { sessionLog: 0, memory: 0 };
  for (const target of targets) {
    if (target.notes.length === 0) continue;
    const path = await resolveSourcePath(target.area, options);
    if (options.signal?.aborted) {
      return { ok: false, code: "aborted", message: "registo cancelado" };
    }
    try {
      await mkdir(dirname(path), { recursive: true });
      await appendFile(path, `${target.notes.map((entry) => entry.line).join("\n")}\n`, {
        encoding: "utf8",
      });
      paths.push(path);
      counts[target.area === "memory" ? "memory" : "sessionLog"] = target.notes.length;
    } catch (error) {
      warnings.push(`${target.area}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  if (paths.length === 0) {
    return {
      ok: false,
      code: "write_failed",
      message: warnings.join("; ") || "nenhuma fonte foi gravada",
    };
  }
  return { ok: true, paths, warnings, notes: notes.map((entry) => entry.note), counts };


