async function resolveSourcePath(area: KdAiArea, options: RememberOptions): Promise<string> {
  const configured = options.sources?.[area];
  if (configured) return resolve(options.cwd ?? process.cwd(), configured);

  const cwd = options.cwd ?? process.cwd();
  const key = `${cwd}\u0000${area}`;
  const cached = resolvedSources.get(key);
  if (cached) return cached;

  const resolved = await runKdAi({ area }, options);
  const path =
    resolved.ok && resolved.source
      ? resolved.source
      : resolve(cwd, DEFAULT_MEMORY_SOURCES[area]);
  resolvedSources.set(key, path);
  return path;
}

