function stringList(value: string[] | undefined): string[] | string {
  if (value === undefined) return [];
  const out: string[] = [];
  for (const item of value) {
    if (typeof item !== "string" || item.trim() === "") {
      return "lista contém item vazio ou não textual";
    }
    out.push(item);
