function normalize(text: string): string {
  return text.normalize("NFC").replace(/\p{White_Space}+/gu, " ").trim();
}

function shortHash(data: string): { value: number; hex: string } {
  const digest = createHash("sha256").update(data, "utf8").digest();
  return {
    value: digest.readUInt32BE(0),
    hex: digest.subarray(0, 4).toString("hex"),
  };
}

function firstSentence(text: string): string {
  if (!text) return "";
  const match = text.match(/^.*?[.!?](?:\s|$)/su);
  return (match?.[0] ?? text).trim();
}

function truncateScalars(text: string, max: number): string {
  const scalars = Array.from(text);
  if (scalars.length <= max) return text;
  return `${scalars.slice(0, max - 1).join("")}…`;
}

function truncateText(text: string, max: number): string {
  const scalars = Array.from(text);
  if (scalars.length <= max) return text;
  return `${scalars.slice(0, max - 1).join("")}…`;
}

function stringArg(args: Record<string, unknown>, key: string): string | undefined {
  const value = args[key];
  return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

function toolPaths(tool: SessionTool): string[] {
  const out: string[] = [];
  for (const key of ["path", "file_path", "file", "files"]) {
    const value = tool.arguments[key];
    if (typeof value === "string" && value.trim()) out.push(value.trim());
    if (Array.isArray(value)) {
      for (const item of value) {
        if (typeof item === "string" && item.trim()) out.push(item.trim());
      }
    }
  }
  return [...new Set(out)];
}

function toolSummary(tool: SessionTool): string {
  const intent = stringArg(tool.arguments, "i");
  const command = stringArg(tool.arguments, "command");
  const path = toolPaths(tool)[0];
  const details = [
    intent ? `intenção: ${intent}` : "",
    command ? `comando: ${command}` : "",
    path ? `caminho: ${path}` : "",
  ].filter(Boolean);
  return `- ${tool.name}${details.length > 0 ? ` (${details.join(" | ")})` : ""}`;
}

function toAnchor(path: string, cwd?: string): string | undefined {
  const trimmed = path.trim().replace(/:\d+(?:-\d+)?$/, "");
