export function buildKdAiArgs(request: KdAiRequest): string[] {
  const area = request.area ?? "memory";
  const args = ["ai", area];
  const query = request.query?.trim();
  if (query) args.push(query);
  if (request.source) args.push("--source", request.source);
  if (request.limit !== undefined) args.push("--limit", String(request.limit));
  args.push("--json");
  return args;
