export function resolveKdBin(options: KdAiOptions = {}): string {
  return (
    options.bin ||
    options.env?.KNUDGE_KD_BIN ||
    process.env.KNUDGE_KD_BIN ||
    process.env.KD_BIN ||
    DEFAULT_KD_BIN
  );
}

export function resolveTimeoutMs(options: KdAiOptions = {}): number {
  if (options.timeoutMs !== undefined) return options.timeoutMs;
  const raw = options.env?.KNUDGE_AI_TIMEOUT_MS || process.env.KNUDGE_AI_TIMEOUT_MS;
  if (!raw) return DEFAULT_TIMEOUT_MS;
